(()=>{'use strict';const T=Tempo,$=id=>document.getElementById(id),ctx=$('tutorial-board').getContext('2d');
const lessons=[
 {title:'第 1 关：先站上据点',description:'中央祭坛的金色格能得分。附近没有敌人时，让青岚走上去；月汐可以留在原地。请选择一种安排。',enemy:{orders:['wait','wait']},choices:[{label:'青岚右移 / 月汐等待',orders:['right','wait']},{label:'两人都等待',orders:['wait','wait']}],success:'青岚走到金格，周围没有贴身敌人：+1 分。月汐的动作不会跟着自动改变。',failure:'没有人站上金格，所以 +0 分。试试让青岚右移。'},
 {title:'第 2 关：防守不等于得分',description:'青岚已经站在金格，但绯烬贴近了他。被敌人贴身压制时，防守也得 0 分。试两种安排，比较结果。',enemy:{orders:['wait','wait']},choices:[{label:'两人都防守',orders:['guard','guard']},{label:'青岚冲击 / 月汐等待',orders:['strike','wait']}],success:'青岚把绯烬推到两格外，压制解除，恢复 +1 分。防守只能挡冲击，不能把贴身敌人赶走。',failure:'虽然防守了，绯烬仍贴在青岚旁边，金格显示“暂停”，本拍 +0 分。'},
 {title:'第 3 关：队友帮你解围',description:'这次绯烬会冲击青岚。月汐已经站在同一祭坛的另一个金格：安排青岚防守、月汐冲击，让一个人保位置，另一个人清敌。',enemy:{orders:['strike','wait']},choices:[{label:'青岚防守 / 月汐冲击',orders:['guard','strike']},{label:'两人都防守',orders:['guard','guard']},{label:'两人都等待',orders:['wait','wait']}],success:'青岚格挡并留在据点；月汐从侧面推走绯烬。两人都没有敌人贴身，各占一个金格，全队本拍 +2 分。这就是两人同拍做不同事情的价值。',failure:'还没有恢复得分。两人防守清不走敌人；等待则会被推离据点。试“青岚防守 / 月汐冲击”。'}
];
let step=0,state,plan,effect=null,animation=null,poses=['idle','idle','idle','idle'],resolved=false,lastDraw=0,completed=new Set();
function scenario(){const s=T.fresh();s.units[0]={...s.units[0],x:step===0?4:5,y:4};s.units[1]={...s.units[1],x:step===2?6:4,y:3};s.units[2]={...s.units[2],x:step===0?9:6,y:4};s.units[3]={...s.units[3],x:9,y:6};return s;}

function resetDemo(){state=scenario();plan=Array.from({length:3},()=>({orders:['wait','wait']}));effect=null;animation=null;poses=poses.map(()=> 'idle');resolved=false;$('demo-title').textContent=lessons[step].title;$('demo-description').textContent=lessons[step].description;$('demo-outcome').textContent='先点一种安排。每关只有一拍，结果会立即解释。';$('demo-status').textContent=`第 ${step+1} / 3 关 · 选择一种安排`;$('demo-next').textContent=step===2?'再看第一关':'下一关 →';$('demo-steps').replaceChildren(...lessons.map((l,i)=>{const b=document.createElement('button');b.textContent=`${completed.has(i)?'✓':i+1} · ${['占点','压制','解围'][i]}`;b.className=i===step?'picked':'';b.onclick=()=>{step=i;resetDemo();};return b;}));$('demo-choices').replaceChildren(...lessons[step].choices.map((c,i)=>{const b=document.createElement('button');b.textContent=c.label;b.onclick=()=>tryChoice(i);return b;}));draw();}
function tryChoice(index){const choice=lessons[step].choices[index];if(!choice)throw Error('无效练习选项');state=scenario();plan=[{orders:[...choice.orders]},{orders:['wait','wait']},{orders:['wait','wait']}];const before=state.units.map(p=>({...p}));effect=T.resolve(state,plan[0],lessons[step].enemy);animation={from:before,start:performance.now()};poses=effect.actions.map((a,i)=>T.actions[a]?'move':a==='guard'&&effect.guardActive[i]?'guard':a==='strike'?'strike':'idle');resolved=true;if(effect.sideGain[0]>0)completed.add(step);$('demo-status').textContent=`本拍我方 +${effect.sideGain[0]} 分`;$('demo-outcome').textContent=effect.sideGain[0]>0?lessons[step].success:lessons[step].failure;Array.from($('demo-choices').children).forEach((b,i)=>b.className=i===index?'picked':'');draw();}
function draw(){const time=performance.now(),age=animation?time-animation.start:0;TempoRenderer.render(ctx,{state,plan,phase:resolved?'run':'plan',selected:0,selectedUnit:step===2?1:0,animation,effect,poses:poses.map(p=>age>650?'idle':p),time});}
function loop(){const time=performance.now();if(window.Match.screen==='intro'&&time-lastDraw>32){draw();lastDraw=time;}requestAnimationFrame(loop);}
$('demo-toggle').onclick=resetDemo;$('demo-next').onclick=()=>{step=(step+1)%lessons.length;resetDemo();};window.Tutorial={getState:()=>({step,state,resolved,completed:[...completed]}),selectStep(i){if(!Number.isInteger(i)||i<0||i>=lessons.length)throw Error('无效练习');step=i;resetDemo();},tryChoice};resetDemo();requestAnimationFrame(loop);
})();
